#include "e198.inc"
#include "kernel.inc"
namespace e199 {
template<bool P>void run199(Context&x,Backend&aux,Models&models,GateSets&gates,const std::vector<float>&Q,const json&c,int K,int L,const std::string&m,Batch&out,std::vector<Work>&work,std::vector<int32_t>&dec,std::vector<double>*profile=nullptr){
 bool profile_base=P&&(m=="GT10"||m=="OPT-B32"||m=="Q8-B32");
 if(!ours(m)&&!profile_base){std::vector<int32_t>chosen;run_actual(x,aux,Q,c,K,L,m,out,work,chosen);dec.assign(out.n*ND,0);return;}
 std::string mode=profile_base?(m=="GT10"?"MAIN":m=="OPT-B32"?"FULL-DIRECT":"DIRECT"):m;
 work.assign(out.n,Work{});dec.assign(out.n*ND,0);if constexpr(P){require(profile,"profile output");profile->assign(out.n*NS,0);}
 std::vector<RouteData>routes;routes.reserve(out.n);
 for(size_t i=0;i<out.n;++i){Clock::time_point t;if constexpr(P)t=Clock::now();auto r=x.router->route(Q.data()+i*x.idx->d);routes.push_back(r);for(int j=0;j<3;++j){out.entries[i*3+j]=r.ids[j];out.profile_distances[i*3+j]=r.distances[j];}if constexpr(P)(*profile)[i*NS]=seconds(t)*1e6;}
 Runner199 runner(x,*models.at({K,200}),gates.count(K)?gates.at(K).get():nullptr);
 for(size_t i=0;i<out.n;++i){auto z=runner.query<P>(Q.data()+i*x.idx->d,routes[i],K,L,mode);std::copy(z.outcome.ids.begin(),z.outcome.ids.end(),out.ids.begin()+i*K);std::copy(z.outcome.values.begin(),z.outcome.values.end(),out.distances.begin()+i*K);work[i]=z.outcome.work;std::copy(z.decision.begin(),z.decision.end(),dec.begin()+i*ND);if constexpr(P)for(int j=1;j<NS;++j)(*profile)[i*NS+j]=z.us[j];}
}
__attribute__((noinline))double timed199(Context&x,Backend&aux,Models&models,GateSets&gates,const std::vector<float>&Q,const json&c,int K,int L,const std::string&m,Batch&dest,std::vector<Work>&w,std::vector<int32_t>&d){auto t=Clock::now();{Batch out(dest.n,K);run199<false>(x,aux,models,gates,Q,c,K,L,m,out,w,d);copy_packet(out,dest);asm volatile(""::"g"(out.ids.data()),"g"(dest.ids.data()):"memory");}return seconds(t);}
void witness199(Context&x,Models&models,GateSets&gates,const std::vector<float>&Q,int K,int L,const std::string&m,const Batch&b,const std::vector<Work>&work,const std::vector<int32_t>&dec,const fs::path&path){
 Runner199 runner(x,*models.at({K,200}),gates.count(K)?gates.at(K).get():nullptr);gzFile wf=gzopen((path/"witness.bin.gz").c_str(),"wb3"),sf=nullptr;require(wf,"witness stream");if(m=="ALWAYS"){sf=gzopen((path/"selection.bin.gz").c_str(),"wb3");require(sf,"feature witness stream");}
 for(size_t i=0;i<b.n;++i){auto*q=Q.data()+i*x.idx->d;auto r=x.router->route(q);Detail199 detail;auto z=runner.query<false>(q,r,K,L,m,&detail,sf!=nullptr);std::vector<int32_t>I;std::vector<float>V;merge_linear(detail.main.data(),detail.D.data(),K,detail.events,I,V);require(I==z.outcome.ids&&!std::memcmp(V.data(),z.outcome.values.data(),4*K),"independent native linear merge");for(int j=0;j<K;++j)require(I[j]==b.ids[i*K+j]&&equal_float(V[j],b.distances[i*K+j]),"actual normal timed packet oracle");require(z.outcome.work==work[i]&&std::equal(z.decision.begin(),z.decision.end(),dec.begin()+i*ND),"replay action and work parity");uint32_t h[4]={uint32_t(i),uint32_t(K),uint32_t(detail.events.size()),uint32_t(z.decision[0])};gzwrite(wf,h,sizeof(h));for(int j=0;j<K;++j){gzwrite(wf,&detail.main[j],4);gzwrite(wf,&detail.D[j],4);}for(auto a:detail.events){gzwrite(wf,&a.id,4);gzwrite(wf,&a.value,4);}if(z.decision[0])gzwrite(wf,&z.decision[1],4);
  if(sf){uint32_t h[2]={uint32_t(i),uint32_t(detail.C.size())};gzwrite(sf,h,sizeof(h));gzwrite(sf,detail.pre.data(),22*4);gzwrite(sf,detail.post.data(),28*4);gzwrite(sf,detail.cpost.data(),12*4);auto rank=ranks(detail.cv);for(size_t j=0;j<rank.size();++j){int32_t id=detail.C[rank[j]];gzwrite(sf,&id,4);gzwrite(sf,detail.features[j].data(),F*4);}}
 }
 require(gzclose(wf)==Z_OK,"witness close");if(sf)require(gzclose(sf)==Z_OK,"selection close");fresh_json(path/"oracle.json",{{"status","PASS_ALL_QUERY_TIMED_LINEAR_WORK_DECISION"},{"queries",b.n}});
}
json gate_labels(const json&c){
 check_threads(c);auto start=Clock::now();fs::path root=c.at("output_dir");fresh_dir(root);Context x(c);auto models=load_models(c);auto gates=load_gates(c);Matrix qm(c.at("queries"));auto Q=qm.copy();auto GT=read_gt(c.at("test_gt"),x.idx->ntotal);json states=json::array();
 for(int K:{1,100}){auto dir=root/("k"+std::to_string(K));fresh_dir(dir);Runner199 runner(x,*models.at({K,200}),nullptr);std::vector<float>features;std::vector<int32_t>targets,mainI,directI,finalI;std::vector<double>times;
  for(size_t i=0;i<qm.n;++i){auto*q=Q.data()+i*x.idx->d;auto t=Clock::now();auto route=x.router->route(q);double route_us=seconds(t)*1e6;Detail199 detail;auto z=runner.query<true>(q,route,K,200,"ALWAYS",&detail,true);z.us[0]=route_us;features.insert(features.end(),detail.pre.begin(),detail.pre.end());features.insert(features.end(),detail.post.begin(),detail.post.end());features.insert(features.end(),detail.cpost.begin(),detail.cpost.end());std::unordered_set<int>G(GT.begin()+i*100,GT.begin()+i*100+K);targets.insert(targets.end(),{hits(detail.main,G),hits(detail.direct,G),hits(z.outcome.ids,G),z.decision[1]});mainI.insert(mainI.end(),detail.main.begin(),detail.main.end());directI.insert(directI.end(),detail.direct.begin(),detail.direct.end());finalI.insert(finalI.end(),z.outcome.ids.begin(),z.outcome.ids.end());times.insert(times.end(),z.us.begin(),z.us.end());if(i%512==0)std::cout<<json{{"stage","gate_labels"},{"dataset",c.at("dataset")},{"K",K},{"query",i}}.dump()<<std::endl;
  }
  write_raw(dir/"features.f32",features);write_raw(dir/"targets.i32",targets);write_raw(dir/"main.i32",mainI);write_raw(dir/"direct.i32",directI);write_raw(dir/"final.i32",finalI);write_raw(dir/"profile.f64",times);states.push_back({{"K",K},{"n",qm.n},{"features",62}});
 }
 json result={{"status","PASS_ACTUAL_MATCHED_CASCADE_GATE_LABELS"},{"states",states},{"seconds",seconds(start)},{"online_GT",false}};fresh_json(root/"complete.json",result);return result;
}
json matrix199(const json&c){
 check_threads(c);auto begin=Clock::now();fs::path root=c.at("output_dir");fresh_dir(root);fresh_json(root/"config.json",c);Context x(c);e194::FastBackend aux(c);auto models=load_models(c);auto gates=load_gates(c);Matrix qm(c.at("queries"));auto Q=qm.copy();std::map<std::pair<int,int>,std::vector<std::string>>groups;for(auto p:c.at("points"))groups[{p.at("K"),p.at("L")}].push_back(p.at("method"));json results=json::array();int ordinal=0,batches=0;
 fresh_json(root/"environment.json",{{"actual_threads",process_threads()},{"cpu",15},{"binding",x.binding},{"online_GT",false},{"stage_names",stage_names},{"normal_path_stage_clocks",false}});
 for(auto&pair:groups){int K=pair.first.first,L=pair.first.second;auto ms=pair.second;size_t n=ms.size();std::vector<std::unique_ptr<Batch>>first(n);std::vector<std::vector<Work>>work(n);std::vector<std::vector<int32_t>>dec(n);std::vector<json>rounds(n,json::array());Batch dest(qm.n,K);
  for(int rep=0;rep<3;++rep)for(size_t offset=0;offset<n;++offset){size_t j=(ordinal+rep+offset)%n;auto m=ms[j];auto path=root/("k"+std::to_string(K))/(m+"_L"+std::to_string(L));if(rep==0){Batch warm(std::min<size_t>(128,qm.n),K);std::vector<Work>w;std::vector<int32_t>d;run199<false>(x,aux,models,gates,Q,c,K,L,m,warm,w,d);}std::vector<Work>w;std::vector<int32_t>d;check_threads(c);double wall=timed199(x,aux,models,gates,Q,c,K,L,m,dest,w,d);check_threads(c);validate(dest,x.idx->ntotal);auto hash=packet_sha(dest);
   if(rep==0){first[j]=std::make_unique<Batch>(dest);work[j]=w;dec[j]=d;dest.save(path/"raw",false);std::vector<uint64_t>flat;for(auto&a:w)flat.insert(flat.end(),a.begin(),a.end());write_raw(path/"work.u64",flat);write_raw(path/"decisions.i32",d);}else{all_same(*first[j],dest);require(w==work[j]&&d==dec[j],"three-round normal work and policy parity");}
   json r={{"round",rep},{"wall_seconds",wall},{"qps",qm.n/wall},{"threads",process_threads()},{"packet_sha256",hash}};rounds[j].push_back(r);fresh_json(path/("round"+std::to_string(rep)+".json"),r);++batches;std::cout<<json{{"dataset",c.at("dataset")},{"window",c.value("window","qualification")},{"K",K},{"L",L},{"method",m},{"round",rep},{"qps",qm.n/wall}}.dump()<<std::endl;
  }
  for(size_t j=0;j<n;++j){auto m=ms[j];auto path=root/("k"+std::to_string(K))/(m+"_L"+std::to_string(L));json profiling=nullptr;
   if(ours(m))witness199(x,models,gates,Q,K,L,m,*first[j],work[j],dec[j],path);else audit_actual(x,Q,c,K,L,m,*first[j],work[j],path);
   if(L==200&&m!="REUSE-SQ"){auto t=Clock::now();Batch prof(qm.n,K);std::vector<Work>w;std::vector<int32_t>d;std::vector<double>us;run199<true>(x,aux,models,gates,Q,c,K,L,m,prof,w,d,&us);double wall=seconds(t);all_same(prof,*first[j]);if(ours(m))require(w==work[j]&&d==dec[j],"profile normal action and work parity");write_raw(path/"profile.f64",us);profiling={{"profile_batch_wall_seconds",wall},{"stage_values",NS},{"queries",qm.n},{"actual_packet_equal",true},{"diagnostic_not_formal_QPS",true}};fresh_json(path/"profile.json",profiling);}
   if(m=="REUSE-SQ"){auto it=std::find(ms.begin(),ms.end(),"GT10");require(it!=ms.end(),"SQ main control");audit_sq(*x.idx,Q,aux,*first[it-ms.begin()],*first[j],path);}
   if(c.value("qualification",false)&&ours(m)&&(m=="ALWAYS"||m=="FAST384"||m=="TEACHER384"||m=="DIST384")){Batch original(qm.n,K);std::vector<Work>w;std::vector<int32_t>d;e198::run198(x,aux,models,Q,c,K,L,old_method(m),original,w,d);all_same(original,*first[j]);require(w==work[j],"inherited selected-action work parity");}
   std::vector<double>walls;for(auto rr:rounds[j])walls.push_back(rr.at("wall_seconds"));std::sort(walls.begin(),walls.end());json p={{"dataset",c.at("dataset")},{"window",c.value("window","qualification")},{"K",K},{"L",L},{"method",m},{"n",qm.n},{"qps",qm.n/walls[1]},{"rounds",rounds[j]},{"profile",profiling},{"all_round_bits_and_work_equal",true}};results.push_back(p);fresh_json(path/"result.json",p);
  }
  for(std::string prefix:{"F","N"}){auto a=std::find(ms.begin(),ms.end(),prefix+"-PRE90"),b=std::find(ms.begin(),ms.end(),prefix+"-PRE90-LATE");if(a!=ms.end()&&b!=ms.end()){all_same(*first[a-ms.begin()],*first[b-ms.begin()]);for(size_t i=0;i<qm.n;++i)for(int d:{0,1,2,3,4,6})require(dec[a-ms.begin()][i*ND+d]==dec[b-ms.begin()][i*ND+d],"same model gate placement action equality");}}
  if(c.value("qualification",false))for(auto pp:{std::pair<std::string,std::string>{"F-FORCE-OFF","GT10"},{"N-FORCE-OFF","Q8-B32"},{"F-FORCE-ON","ALWAYS"},{"N-FORCE-ON","ALWAYS"}}){auto a=std::find(ms.begin(),ms.end(),pp.first),b=std::find(ms.begin(),ms.end(),pp.second);if(a!=ms.end()&&b!=ms.end())all_same(*first[a-ms.begin()],*first[b-ms.begin()]);}
  ++ordinal;
 }
 json result={{"status","PASS_E199_COMPLETE_WALL_MATRIX_AND_PROFILE_PARITY"},{"points",results.size()},{"batches",batches},{"results",results},{"native_process_seconds",seconds(begin)},{"GT_read",false}};fresh_json(root/"complete.json",result);return json{{"status",result.at("status")},{"points",results.size()},{"batches",batches},{"seconds",seconds(begin)}};
}
}
int main(int argc,char**argv){try{using namespace e199;require(argc==3,"mode config");auto c=read_json(argv[2]);std::string mode=argv[1];json v;if(mode=="gate_labels")v=gate_labels(c);else if(mode=="matrix")v=matrix199(c);else throw std::runtime_error("unknown mode");std::cout<<v.dump()<<std::endl;return 0;}catch(const std::exception&e){std::cerr<<"FATAL E199 "<<e.what()<<std::endl;return 2;}}
